 bind('[data-conjure-layer]','click',()=>{try{const s=coordinator.document.sections.find(s=>s.blocks[selected]);if(!s)return;canvas.cancel();const bp=canvas.breakpoint,l=s.layouts[bp],z=Math.max(...Object.values(l.placements).map(e=>e.value.z))+1;coordinator.layer({sectionId:s.id,breakpoint:bp,blockId:selected,z});}catch(e){say(e.message);}});
