 function add(type,content,presentation){const next=coordinator.document,s=next.sections[0],id='block:'+type+':'+d.defaultView.crypto.randomUUID();s.order.push(id);s.blocks[id]={id,type,version:1,content,presentation,capabilities:{move:true,resize:true,layer:true,edit:type==='button',remove:false}};for(const [bp,l] of Object.entries(s.layouts)){const row=l.rows,rows=type==='image'?8:2,cols=Math.min(l.grid.columns,type==='image'?12:8);l.placements[id]={source:bp==='desktop'?'manual':'generated',value:{col:0,row,cols,rows,z:0,visible:true,locked:false}};l.rows=row+rows+l.grid.trailingRows;}validateComposition(next,readBody(),article.id,{assets,usage});coordinator.transact('Add '+type,next);canvas.select(id);}
